def is_explain_deselections_enabled(config: Config) -> bool:
    if config.getoption('explain_deselections') or config.getini('explain_deselections'):
        return True
    cli_opts = ['explain_deselections_verbose', 'explain_deselections_sort_by', 'explain_deselections_show_total', 'explain_deselections_show_stats', 'explain_deselections_reason_filter', 'explain_deselections_warn_if_exceeds', 'explain_deselections_fail_if_exceeds', 'explain_deselections_min_count', 'explain_deselections_reasons_cap', 'explain_deselections_min_delta', 'explain_deselections_output', 'explain_deselections_format', 'explain_deselections_max_nodeids', 'explain_deselections_nodeids_order', 'explain_deselections_json_no_nodeids', 'explain_deselections_json_pretty', 'explain_deselections_csv_with_delta', 'explain_deselections_junit', 'explain_deselections_baseline', 'explain_deselections_fail_on_new', 'explain_deselections_update_baseline']
    for opt in cli_opts:
        val = config.getoption(opt)
        if val is not None and val is not False:
            return True
    ini_opts = ['explain_deselections_min_count', 'explain_deselections_format', 'explain_deselections_fail_if_exceeds', 'explain_deselections_max_nodeids', 'explain_deselections_nodeids_order', 'explain_deselections_junit']
    for opt in ini_opts:
        val = config.getini(opt)
        if val is not None and val != '':
            return True
    return False

def _parse_int_opt(val: Any, opt_name: str) -> int:
    if val is None or val == '':
